import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

product_reduce_dim1_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <stdexcept>

__global__ void product_reduce_dim1_kernel(const float* x, float* out, int B, int D1, int D2) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = B * D2;
    if (idx < total) {
        int b = idx / D2;
        int col = idx % D2;
        float product_val = 1.0f;
        int base = b * D1 * D2 + col;
        for(int j = 0; j < D1; j++) {
            product_val *= x[base + j * D2];
        }
        out[idx] = product_val;
    }
}

torch::Tensor product_reduce_dim1_cuda(torch::Tensor x, int64_t dim) {
    if (dim != 1) {
        throw std::runtime_error("This custom kernel only supports reduction on dim=1.");
    }
    x = x.contiguous();
    auto B = x.size(0);
    auto D1 = x.size(1);
    auto D2 = x.size(2);

    auto out = torch::zeros({B, D2}, x.options());
    const int block_size = 256;
    const int num_blocks = (B * D2 + block_size - 1) / block_size;

    product_reduce_dim1_kernel<<<num_blocks, block_size>>>(
        x.data_ptr<float>(),
        out.data_ptr<float>(),
        B, D1, D2
    );

    return out;
}
"""

product_reduce_dim1_cpp_source = "torch::Tensor product_reduce_dim1_cuda(torch::Tensor x, int64_t dim);"

product_reduce = load_inline(
    name="product_reduce",
    cpp_sources=product_reduce_dim1_cpp_source,
    cuda_sources=product_reduce_dim1_source,
    functions=["product_reduce_dim1_cuda"],
    verbose=False
)

class ModelNew(nn.Module):
    """
    Optimized model that performs product reduction over a dimension using a custom CUDA kernel.
    """
    def __init__(self, dim: int):
        super(ModelNew, self).__init__()
        self.dim = dim
        self.reduce = product_reduce

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.reduce.product_reduce_dim1_cuda(x, self.dim)
